const defaultState=()=>({version:2,nickname:'你',passcode:'1204',wall:'jin',customWall:'',dark:false,proactive:true,haptics:true,language:'中文',chats:Object.fromEntries(members.map(m=>[m.id,[]])),memories:[],notes:[],uploads:[],seen:false,verifiedNews:[]});
let state=defaultState(),storageOK=true;try{const raw=JSON.parse((localStorage.getItem('withyou-phone-scripted-v1')||localStorage.getItem('withyou-v2'))||'null');if(raw&&raw.version===2)state={...state,...raw,chats:{...state.chats,...raw.chats}}}catch(e){storageOK=false}
