let page='lock',roomId='jin',chatMode='kkt',tab='chats',pass='',errors={},pending=new Set(),lastActive=Date.now(),cameraStream=null,clockTab='world',stopStart=0,stopElapsed=0,stopRunning=false,photoTarget='album',searchText='',news=null;
