const avatar=(m,cls='')=>`<span class="avatar ${cls}" style="--av:${m.color}">${m.photo?`<img src="${m.photo}" alt="${m.name}" data-fallback="${escape(m.emoji||'🙂')}" onerror="this.replaceWith(document.createTextNode(this.dataset.fallback))">`:m.emoji}</span>`;
function toast(text){$('#toast').className='toast';$('#toast').textContent=text;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{$('#toast').textContent='';$('#toast').className=''},3300)}
function applyAppearance(){const w=$('#wallpaper');w.style.background=state.wall==='custom'&&state.customWall?`url("${state.customWall}") center / cover`:walls[state.wall]||walls.dusk;w.classList.toggle('custom',state.wall==='custom');phone.classList.toggle('dark-mode',state.dark)}
function styleStatus(dark){$('#status').classList.toggle('dark',dark);$('#home').classList.toggle('dark',dark)}
function stopCamera(){if(cameraStream){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null}}
function navigateLegacy(next){if(page==='camera'&&next!=='camera')stopCamera();page=next;searchText='';$('#overlay').innerHTML='';render();lastActive=Date.now()}
function updateTime(){const d=new Date();$('#status-time').textContent=d.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});document.querySelectorAll('[data-time]').forEach(el=>el.textContent=d.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false}));if(page==='clock')updateClock()}
function render(){applyAppearance();styleStatus(!['home','lock','passcode','camera'].includes(page));if(page==='lock')renderLock();else if(page==='passcode')renderPasscode();else if(page==='home')renderHome();else if(page==='chat')renderChat();else if(page==='kkt')renderRooms();else if(page==='messages')renderSMSList();else if(page.startsWith('sms:'))renderSMS(page.slice(4));else if(page==='shop')renderShop();else if(page==='mentions')renderMentions();else if(page==='instagram')renderInstagram();else if(page==='contacts')renderContacts();else if(page==='contact')renderContact();else if(page==='settings')renderSettings();else if(page.startsWith('setting:'))renderSetting(page.split(':')[1]);else if(page==='notes')renderNotes();else if(page.startsWith('note:'))renderNote(page.split(':')[1]);else if(page==='photos')renderPhotos();else if(page==='clock')renderClock();else if(page==='news')renderNews();else if(page==='safari')renderSafari();else if(page==='camera')renderCamera();else if(page==='phone')renderDial();else if(page==='search')renderSearch();else if(page==='calendar')renderCalendar();else if(page==='spotify')renderSpotify();updateTime();afterRender()}
function renderLock(){const d=new Date();screen.innerHTML=`<div class="screen lock"><div class="lock-symbol">${icon('lock')}</div><div class="lock-date">${d.toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</div><div class="lock-clock" data-time></div><div class="lock-sub">a little closer to you</div><button class="lock-notification" data-action="unlock"><span class="mini-app">${icon('chat')}</span><span><strong>WITH YOU</strong><p>${state.seen?'欢迎回来，你的故事还在这里。':'你的手机，已经准备好了。'}</p></span><small>现在</small></button><div class="lock-bottom"><button class="circle-glass" data-action="flash" aria-label="手电筒">${icon('flash')}</button><button class="unlock-label" data-action="unlock">轻点或向上滑动解锁</button><button class="circle-glass" data-nav="camera" aria-label="相机">${icon('camera')}</button></div></div>`}
function unlock(){if(state.passcode)navigate('passcode');else enterHome()}
function enterHome(){state.seen=true;save();navigate('home');if(!storageOK)toast('当前浏览器无法保存数据，请先检查隐私设置。');if(!state.introduced){state.introduced=true;save();showIntro()}}
function renderPasscode(){screen.innerHTML=`<div class="screen passcode"><div style="display:flex;justify-content:center">${icon('lock')}</div><h3>输入密码</h3><div class="code-dots">${Array.from({length:4},(_,i)=>`<i class="${pass.length>i?'filled':''}"></i>`).join('')}</div><div class="error" id="pass-error"></div><div class="dial-pad">${['1','2','3','4','5','6','7','8','9','','0','⌫'].map(n=>n?`<button data-digit="${n}">${n}</button>`:'<span></span>').join('')}</div><button class="cancel" data-nav="lock">取消</button><button class="cancel" data-action="forgot">忘记密码？</button></div>`}
function inputDigit(n){pass=n==='⌫'?pass.slice(0,-1):(pass+n).slice(0,4);renderPasscode();if(pass.length===4){if(pass===state.passcode){pass='';enterHome()}else{pass='';$('#pass-error').textContent='密码不正确，请重试';setTimeout(()=>{if(page==='passcode')renderPasscode()},700)}}}
const apps=[['kkt','KakaoTalk','yellow','chat'],['photos','照片','white','photos'],['notes','备忘录','white','notes'],['news','动态','ig','ig'],['clock','时钟','black','clock'],['calendar','日历','white','calendar'],['camera','相机','gray','camera'],['settings','设置','gray','settings'],['contacts','通讯录','white','users'],['safari','Safari','white','compass'],['messages','信息','green','message'],['music','音乐','pink','music']];
function tileContent(type){if(type==='photos')return`<span class="flower">${Array.from({length:8},(_,i)=>`<i style="--r:${i*45}deg;--h:${i*45}"></i>`).join('')}</span>`;if(type==='notes')return'<span class="notes-icon"></span>';if(type==='clock')return'<span class="clock-icon"><b></b></span>';if(type==='calendar')return`<span class="calendar-icon"><small>${new Date().toLocaleDateString('zh-CN',{weekday:'long'})}</small>${new Date().getDate()}</span>`;return icon(type)}
function appButtonLegacy(a){return`<button class="app" data-app="${a[0]}" aria-label="${a[1]}"><span class="app-tile ${a[2]}">${tileContent(a[3])}</span><span class="app-label">${a[1]}</span></button>`}
function renderHomeLegacy(){const d=new Date();screen.innerHTML=`<div class="screen home-screen"><div class="widget-row"><button class="widget calendar-widget" data-app="calendar"><small>${d.toLocaleDateString('zh-CN',{weekday:'long'})}</small><div class="big">${d.getDate()}</div><p>留一点时间给自己</p></button><button class="widget weather-widget" data-app="clock"><small>Seoul</small><div class="big" id="seoul-widget"></div><span class="weather-sun">☾</span><p>此刻，也许在想你</p><span class="fiction">首尔当地时间</span></button></div><div class="app-grid">${apps.map(appButton).join('')}</div><button class="search-home" data-nav="search">${icon('search')}搜索</button><div class="dock">${[['phone','电话','green','phone'],['kkt','KakaoTalk','yellow','chat'],['safari','Safari','white','compass'],['messages','信息','green','message']].map(appButton).join('')}</div></div>`;$('#seoul-widget').textContent=new Date().toLocaleTimeString('en-GB',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit'})}
function shell(title,body,options={}){screen.innerHTML=`<div class="app-page ${options.cls||''}"><div class="page-nav"><button data-nav="${options.back||'home'}">${icon('back')}${options.backLabel||'返回'}</button><h3>${options.navTitle||''}</h3>${options.action?`<button data-action="${options.action}" aria-label="${options.actionLabel||'更多'}">${options.actionIcon?icon(options.actionIcon):options.actionText||''}</button>`:'<span style="width:35px"></span>'}</div><div class="page-scroll">${title?`<h2 class="page-title">${title}</h2>`:''}${body}</div>${options.footer||''}</div>`}
function preview(m){const a=state.chats[m.id];const last=a[a.length-1];return last?(last.image?'[照片]':last.text):m.id==='jin'?'置顶 · 从一句「在吗」开始':m.hint}
function renderRoomsLegacy(im=false){chatMode=im?'imessage':'kkt';const q=searchText.toLowerCase();const filtered=members.filter(m=>(m.name+m.en).toLowerCase().includes(q));screen.innerHTML=`<div class="app-page chat-app"><div class="chat-top"><h2>${im?'信息':'聊天'}</h2><button data-action="contacts" aria-label="新建聊天">${icon('edit')}</button></div><div class="page-scroll"><div class="search-box">${icon('search')}<input id="room-search" placeholder="搜索联系人" value="${escape(searchText)}" aria-label="搜索联系人"></div>${!im?`<div class="chat-intro">${icon('heart')}<span><strong>${escape(state.nickname)}的日常，从这里开始</strong>没有预设剧本，聊聊你今天的生活。</span></div>`:''}<div class="room-list">${filtered.map(m=>{const a=state.chats[m.id],last=a[a.length-1];return`<button class="room" data-room="${m.id}">${avatar(m)}<span class="room-info"><strong>${m.name}${m.id==='jin'?' <span style="color:#bf9bab">♡</span>':''}</strong><p>${escape(preview(m))}</p></span><span class="room-meta"><time>${last?time(last.at):''}</time>${m.id==='jin'?'<span class="pin">⌖</span>':''}</span></button>`}).join('')}</div></div>${!im?`<nav class="tabbar"><button data-nav="contacts">${icon('user')}朋友</button><button class="active" data-nav="kkt">${icon('chat')}聊天</button><button data-nav="news">${icon('globe')}动态</button><button data-nav="settings">${icon('more')}更多</button></nav>`:''}</div>`}
function openRoom(id,mode){if(state.unread){state.unread[id]=0;save()}roomId=id;chatMode=mode||chatMode;if(page==='chat'){renderChat();afterRender()}else navigate('chat')}
function time(at){return new Date(at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})}
function renderChatLegacy(){const m=members.find(m=>m.id===roomId);const messages=state.chats[m.id];screen.innerHTML=`<div class="app-page conversation ${chatMode==='imessage'?'imessage':''}"><div class="conv-head"><button class="icon-btn" data-nav="${chatMode==='imessage'?'messages':'kkt'}" aria-label="返回聊天列表">${icon('back')}</button>${avatar(m)}<div class="heading"><strong>${m.name}${m.id==='jin'?' ♡':''}</strong><small>${pending.has(m.id)?'正在输入…':m.relation}</small></div><button class="icon-btn" data-action="chat-more" aria-label="聊天设置">${icon('more')}</button></div><div class="messages" id="messages"><div class="date-chip">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric'})} · 只属于这一部手机</div>${messages.length?messages.map(renderMessage).join(''):`<div class="empty-chat">${avatar(m)}<strong>${m.name}</strong><div>${m.hint}</div><div class="suggestions">${['在吗','今天过得怎么样？','想和你聊一会儿'].map(s=>`<button data-suggest="${s}">${s}</button>`).join('')}</div></div>`}${pending.has(m.id)?`<div class="message-row them"><div class="bubble typing"><span></span><span></span><span></span></div></div>`:''}${errors[m.id]?`<div class="chat-error" role="alert">${escape(errors[m.id])}<div><button data-action="retry">重新发送</button><button data-nav="setting:ai">聊天连接设置</button></div></div>`:''}</div><form class="compose" id="compose"><button type="button" class="icon-btn" data-action="send-photo" aria-label="发送照片">${icon('plus')}</button><div class="input-wrap"><textarea id="message-input" rows="1" placeholder="${pending.has(m.id)?'可以先写下一句…':'输入消息…'}" maxlength="3000" aria-label="输入消息"></textarea><button type="submit" class="send" ${pending.has(m.id)?'disabled':''} aria-label="发送">${icon('arrow')}</button></div></form></div>`;const list=$('#messages');list.scrollTop=list.scrollHeight;$('#compose').addEventListener('submit',e=>{e.preventDefault();sendMessage()});$('#message-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendMessage()}})}
function renderMessage(msg){return`<div class="message-row ${msg.role==='user'?'me':'them'}"><div class="bubble">${msg.image?`<img src="${escape(msg.image)}" alt="发送的照片">`:''}${msg.text?escape(msg.text):''}</div><time>${time(msg.at)}</time></div>`}
async function sendMessage(text,photo,retry=false,proactive=false){if(SCRIPTED_MODE){toast('请使用当前场景下方的预设回复');return}const id=roomId;if(pending.has(id))return;const input=$('#message-input');text=(text??input?.value??'').trim();if(!retry&&!proactive&&!text&&!photo)return;const draft=input?.value||'';if(!retry&&!proactive){state.chats[id].push({id:uid(),role:'user',text,image:photo||null,at:Date.now()});if(!save()){state.chats[id].pop();return}if(input)input.value='';if(id==='jin'&&text)worldUserMessage(text)}delete errors[id];if(!sessionKey&&!siteConfig.ready){errors[id]='聊天服务尚未由站长接通。访客不需要注册 API；站长只需在服务器设置 DEEPSEEK_API_KEY。消息已保存在本机。';if(page==='chat')renderChat();return}pending.add(id);if(page==='chat')renderChat();try{const history=state.chats[id].filter(m=>id!=='jin'||!state.romance?.storyStartAt||m.at>=state.romance.storyStartAt).slice(-50).map(({role,text,image})=>({role,text,image}));const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json','X-DeepSeek-Key':sessionKey},body:JSON.stringify({member:id,nickname:state.nickname,language:state.language,messages:history,memories:state.memories.slice(-30),news:state.verifiedNews.slice(-5),storyContext:currentStoryContext(),proactive}),signal:AbortSignal.timeout(45000)});let data;try{data=await response.json()}catch{throw Error('连接返回了异常内容，请稍后重试。')}if(!response.ok)throw Error(data.error||'暂时无法连接，请稍后重试。');if(!Array.isArray(data.messages)||!data.messages.length)throw Error('这次没有收到回复，请重试。');const replyTurn=uid();for(let i=0;i<data.messages.length;i++){if(i)await new Promise(r=>setTimeout(r,Math.min(1100,250+data.messages[i].length*18)));state.chats[id].push({id:uid(),role:'assistant',text:data.messages[i],at:Date.now(),turn:replyTurn});save();if(page==='chat'&&roomId===id){const draft=$('#message-input')?.value||'';renderChat();$('#message-input').value=draft}}save();lastActive=Date.now();notifyIncoming(id,data.messages[0]);if(id==='jin'&&!proactive)worldAfterChat()}catch(e){errors[id]=e.name==='TimeoutError'?'这次回复超时了，消息已保存，可以重新发送。':e.message}finally{pending.delete(id);if(page==='chat'&&roomId===id){const currentDraft=$('#message-input')?.value||'';renderChat();$('#message-input').value=currentDraft}if(page==='kkt')renderRooms();else if(page==='messages')renderSMSList()}}
function renderContactsLegacy(){shell('朋友',`<div class="settings-profile">${avatar({emoji:state.nickname[0]||'我',color:'#e2d9ea'})}<div><strong>${escape(state.nickname)}</strong><p>我的个人资料</p></div><button class="icon-btn" data-nav="setting:profile" aria-label="编辑个人资料">${icon('edit')}</button></div><div class="group-label">朋友 ${members.length}</div>${members.map(m=>`<button class="room" data-contact="${m.id}">${avatar(m)}<span class="room-info"><strong>${m.name}</strong><p>${m.en} · ${m.relation}</p></span><span class="chevron">›</span></button>`).join('')}`,{back:'kkt'})}
function renderContactLegacy(){const m=members.find(m=>m.id===roomId);shell('',`<div class="contact-detail">${avatar(m)}<h2>${m.name}</h2><p>${m.en} · ${m.relation}</p><div class="contact-actions"><button data-room="${m.id}"><span class="icon-btn">${icon('chat')}</span>聊天</button><button data-action="character-info"><span class="icon-btn">${icon('book')}</span>人物资料</button></div></div><div class="help-card"><span class="step-no">YOUR CONNECTION</span><p>${m.id==='jin'?'在这段虚构关系里，你决定如何认识、是否恋爱和怎样继续生活。':'可以聊音乐、日常，或者一起开个玩笑。朋友不会自动知道你的私人关系。'}</p></div>`,{back:'contacts'})}
