function renderNote(id){const n=state.notes.find(n=>n.id===id);if(!n){navigate('notes');return}screen.innerHTML=`<div class="app-page notes-list"><div class="page-nav"><button data-nav="notes">${icon('back')}备忘录</button><h3>自动保存</h3><button data-action="delete-note" data-note-id="${id}" aria-label="删除备忘录">${icon('trash')}</button></div><textarea class="note-editor" id="note-editor" placeholder="写点什么…">${escape(n.text)}</textarea></div>`;$('#note-editor').addEventListener('input',e=>{n.text=e.target.value;n.at=Date.now();save()})}
