function renderNewsLegacy(){shell('动态',`<div class="chat-intro">${icon('globe')}<span><strong>现实的消息，故事的背景。</strong>公开资料与虚构对话分开记录。</span></div><div class="news-card"><small>OFFICIAL TOUR · 来源快照 2026.10.24</small><h3>BTS WORLD TOUR<br>公开行程</h3>${snapshot.map(s=>`<div class="world-row" style="padding:12px 0"><div><small>${s.date}</small><strong style="font-size:15px;font-weight:500">${s.cn}</strong></div><span style="font-size:9px;color:#ad9bb8;max-width:100px;text-align:right">${s.venue}</span></div>`).join('')}<p>日期为演出地当地日期。这里只表示已公布的场次，不代表成员的实时位置。请以官方最新公告为准。</p><a href="https://bighitsmusic.com/bts/tour" target="_blank" rel="noopener noreferrer">查看完整官方巡演日程 ↗</a></div><div class="news-card"><span class="news-tag">官方来源检查</span><p id="news-status">${news?escape(news.status):'点击刷新检查官方巡演页面是否可读取。IG / Weverse 新帖自动同步暂未接通。'}</p><button class="secondary" data-action="refresh-news">刷新官方来源</button></div>${state.verifiedNews.map((n,i)=>`<div class="news-card"><small>手动添加 · ${escape(n.date)}</small><h3>${escape(n.text)}</h3><a href="${escape(n.url)}" target="_blank" rel="noopener noreferrer">查看原始来源 ↗</a><button class="icon-btn" data-remove-news="${i}" aria-label="删除动态">${icon('trash')}</button></div>`).join('')}<div class="form-card"><label for="news-text">添加已核验的公开动态</label><textarea id="news-text" maxlength="700" placeholder="例如：某月某日，Jin 发布了……（仅填写你已确认的内容）"></textarea><input id="news-url" type="url" placeholder="公开原文链接 https://…" style="margin-top:8px"><button class="primary" data-action="add-news">加入聊天背景</button><p>手动记录是你提供的背景，不等于本站独立核实。请勿添加未经证实的行踪。</p></div><a class="browser-card" href="https://weverse.io/bts/artist" target="_blank" rel="noopener noreferrer"><strong>Weverse · BTS ↗</strong><p>前往官方平台查看成员新帖与直播</p></a><a class="browser-card" href="https://www.instagram.com/jin/" target="_blank" rel="noopener noreferrer"><strong>Instagram · @jin ↗</strong><p>前往官方账号查看新帖</p></a>`,{action:'refresh-news',actionIcon:'globe',actionLabel:'刷新官方来源'})}
function renderClockLegacy(){shell('时钟',`<div class="clock-tabs"><button class="${clockTab==='world'?'active':''}" data-clock="world">世界时钟</button><button class="${clockTab==='stopwatch'?'active':''}" data-clock="stopwatch">秒表</button></div>${clockTab==='world'?`<div class="world-list">${[['Asia/Seoul','首尔','SEOUL'],['UTC','伦敦','LONDON'],['Asia/Shanghai','北京','BEIJING']].map(([zone,name,en])=>`<div class="world-row"><div><small>${en}</small><strong>${name}</strong></div><div class="city-time" data-zone="${zone}"></div></div>`).join('')}</div><p class="explain">一点时差，也挡不住想说的话。</p>`:`<div class="stopwatch" id="stopwatch">00:00.00</div><div class="stop-controls"><button data-action="reset-stopwatch">复位</button><button class="go" data-action="toggle-stopwatch">${stopRunning?'停止':'开始'}</button></div>`}`);updateClock()}
function updateClock(){document.querySelectorAll('[data-zone]').forEach(el=>el.textContent=new Date().toLocaleTimeString('en-GB',{timeZone:el.dataset.zone,hour:'2-digit',minute:'2-digit'}));const el=$('#stopwatch');if(el){const t=stopElapsed+(stopRunning?Date.now()-stopStart:0);el.textContent=String(Math.floor(t/60000)).padStart(2,'0')+':'+String(Math.floor(t/1000)%60).padStart(2,'0')+'.'+String(Math.floor(t/10)%100).padStart(2,'0')}}
function renderSafariLegacy(){shell('Safari',`<div class="browser-bar">${icon('lock').replace('class="svg-icon "','style="display:inline;width:11px;height:11px"')} 你的起始页</div><h3 style="font-size:19px;font-weight:500;margin-bottom:20px">个人收藏</h3><a class="browser-card" href="https://weverse.io/bts" target="_blank" rel="noopener noreferrer"><strong>Weverse · BTS ↗</strong><p>官方社区与公开公告</p></a><a class="browser-card" href="https://bighitsmusic.com/bts/tour" target="_blank" rel="noopener noreferrer"><strong>BTS TOUR ↗</strong><p>巡演日期，以官方最新日程为准</p></a><a class="browser-card" href="https://magazine.weverse.io" target="_blank" rel="noopener noreferrer"><strong>Weverse Magazine ↗</strong><p>访谈与音乐，慢慢读。</p></a><a class="browser-card" href="https://platform.deepseek.com/api_keys" target="_blank" rel="noopener noreferrer"><strong>DeepSeek 开放平台 ↗</strong><p>配置聊天模型</p></a><p class="privacy-note">收藏链接在新标签页中打开。</p>`)}
function renderCameraLegacy(){screen.innerHTML=`<div class="app-page camera-screen"><div class="page-nav"><button data-nav="home" style="color:white">${icon('back')}返回</button><h3>相机</h3><span></span></div><div class="camera-view"><p id="camera-hint">相机尚未打开<br>点击下方按钮后，浏览器会询问相机权限。<br><button class="secondary" data-action="start-camera">打开设备相机</button></p><video id="camera-video" autoplay playsinline muted hidden></video></div><div class="camera-controls"><button data-nav="photos" aria-label="打开相册">${icon('image')}</button><button class="shutter" data-action="capture" aria-label="拍照"></button><button data-action="flip-camera" aria-label="切换摄像头">${icon('camera')}</button></div></div>`}
let facing='user';async function startCamera(){if(!navigator.mediaDevices?.getUserMedia){toast('当前浏览器不支持相机，请在 HTTPS 页面中打开。');return}try{stopCamera();cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:facing},audio:false});if(page!=='camera'){stopCamera();return}$('#camera-video').srcObject=cameraStream;$('#camera-video').hidden=false;$('#camera-hint').hidden=true}catch(e){toast('相机未能打开，你仍然可以从相册上传照片。')}}
function renderDial(){shell('电话',`<div class="dial-number" id="dial-number"></div><div class="dial-pad">${['1','2','3','4','5','6','7','8','9','*','0','#'].map(n=>`<button data-dial="${n}">${n}</button>`).join('')}</div><button class="call-btn" data-action="dial-call" aria-label="拨号">${icon('phone')}</button><p class="privacy-note" style="text-align:center">拨号盘为界面模拟，不会拨打真实电话。</p><button class="secondary" data-nav="contacts">通讯录</button>`)}
