function updateSearch(q){const result=$('#search-results');result.innerHTML=apps.filter(a=>a[1].toLowerCase().includes(q.toLowerCase())).map(a=>`<button class="setting-row" data-app="${a[0]}">${icon(a[3])}<span>${a[1]}</span><span class="chevron">›</span></button>`).join('')+members.filter(m=>(m.name+m.en).toLowerCase().includes(q.toLowerCase())).map(m=>`<button class="room" data-room="${m.id}">${avatar(m)}<strong>${m.name}</strong></button>`).join('')}
function modal(title,body,buttons){$('#overlay').innerHTML=`<div class="sheet-backdrop"><div class="sheet" role="dialog" aria-modal="true" aria-label="${escape(title)}"><button class="sheet-close" data-action="close-overlay" aria-label="关闭">×</button><h3>${title}</h3>${body}${buttons||'<button class="primary" data-action="close-overlay">知道了</button>'}</div></div>`}
function showIntro(){if(SCRIPTED_MODE){showRomanceSetup();return}modal('欢迎来到你的手机',`<div class="intro-logo">with you ✳</div><p>这里是一个虚构的平行世界。这部手机属于你；如何与硕珍相识、相爱，由你慢慢决定。</p><p>先到设置里修改昵称，连接你站长配置的 DeepSeek API，再开始聊天。初始锁屏密码是 <strong>1204</strong>。</p><p>聊天保存在当前浏览器，AI 回复不是真人消息。没有接通模型时，我们会明确提示。</p>`,'<button class="primary" data-nav="setting:profile">先设置我的昵称</button><button class="secondary" data-action="close-overlay">先逛逛手机</button>')}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='with-you-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已导出，请妥善保存。')}
async function refreshNews(){news={status:'正在读取官方巡演页面…'};renderNews();try{const r=await fetch('/api/news',{signal:AbortSignal.timeout(15000)});const d=await r.json();news={status:d.ok?`官方页面已于 ${new Date(d.checkedAt).toLocaleString('zh-CN')} 读取。聊天可参考该页面摘要；上方场次仍为标注日期的资料快照。`:d.error||'官方来源暂时无法读取，请打开官方链接查看。'}}catch{news={status:'未能连接官方来源。没有生成或伪造新动态，请使用官方链接查看。'}}if(page==='news')renderNews()}
function validUrl(s){try{const u=new URL(s);return u.protocol==='https:'&&!u.username&&!u.password}catch{return false}}
async function testKey(){const field=$('#api-key');const key=field.value.trim();if(!key){toast('请先填写 API Key。');return}sessionKey=key;try{sessionStorage.setItem('withyou-gemini',key)}catch{}const out=$('#key-result');out.hidden=false;out.textContent='正在检查密钥与可用模型…';try{const r=await fetch('/api/test',{method:'POST',headers:{'X-DeepSeek-Key':key},signal:AbortSignal.timeout(20000)});const d=await r.json();if(page==='setting:ai'&&$('#key-result'))$('#key-result').textContent=r.ok?'连接成功，可以开始聊天了。当前使用 '+d.model+'。':d.error||'连接失败，请核对密钥。'}catch{if(page==='setting:ai'&&$('#key-result'))$('#key-result').textContent='连接超时或网络不可用，请重试。'}}
async function actions(action,el){switch(action){case'unlock':unlock();break;case'forgot':modal('重置游戏锁屏密码','<p>锁屏只是游戏交互，不保护浏览器里的真实数据。你可以把它重置为初始密码 1204，聊天记录不会清除。</p>','<button class="primary" data-action="reset-code">重置为 1204</button><button class="secondary" data-action="close-overlay">取消</button>');break;case'reset-code':state.passcode='1204';pass='';save();$('#overlay').innerHTML='';toast('游戏锁屏密码已重置为 1204');break;case'close-overlay':$('#overlay').innerHTML='';break;case'contacts':navigate('contacts');break;case'flash':phone.classList.toggle('flash-on');phone.style.filter=phone.classList.contains('flash-on')?'brightness(1.25)':'';toast('模拟手电筒'+(phone.classList.contains('flash-on')?'已开启':'已关闭'));break;case'save-profile':{const nick=$('#nickname').value.trim();if(!nick){toast('写一个你喜欢的昵称吧。');return}state.nickname=nick.slice(0,24);state.language=$('#language').value;save();toast('资料已保存');navigate('settings');break}case'save-key':await testKey();break;case'remove-key':sessionKey='';try{sessionStorage.removeItem('withyou-gemini')}catch{}renderSetting('ai');toast('密钥已移除');break;case'upload-wall':$('#wallpaper-file').click();break;case'save-code':{const old=$('#old-code')?.value;if(state.passcode&&old!==state.passcode){toast('当前密码不正确');return}const code=$('#new-code').value;if(!/^\d{4}$/.test(code)){toast('请输入四位数字');return}if(code!==$('#confirm-code').value){toast('两次输入的密码不一致');return}state.passcode=code;save();toast('密码已更新');navigate('settings');break}case'disable-code':if(state.passcode&&$('#old-code')?.value!==state.passcode){toast('请先输入当前密码');return}state.passcode='';save();navigate('settings');toast('锁屏密码已关闭');break;case'add-memory':{const text=$('#memory').value.trim();if(!text)return;if(state.memories.length>=30){toast('最多保存 30 条重要记忆，请先删掉不需要的。');return}state.memories.push(text.slice(0,350));save();renderSetting('memory');toast('已经记下了');break}case'lock-now':navigate('lock');break;case'reset-data':if(pending.size){toast('请等待正在进行的回复结束后再重置');return}modal('清空这部手机？','<p>本浏览器里的聊天、备忘录、记忆和上传照片都会删除。请先导出备份。此操作无法撤销。</p>','<button class="primary" style="background:#bc7a8c" data-action="confirm-reset">确认清空全部数据</button><button class="secondary" data-action="close-overlay">取消</button>');break;case'confirm-reset':stopWorldVoice();if(worldBubbleTimer)clearTimeout(worldBubbleTimer);worldSceneActive=false;state=defaultState();initializeWorldState();save();sessionKey='';try{sessionStorage.removeItem('withyou-gemini')}catch{}navigate('lock');toast('手机已恢复初始状态');break;case'new-note':{const n={id:uid(),text:'',at:Date.now()};state.notes.unshift(n);save();navigate('note:'+n.id);break}case'delete-note':{const id=el.dataset.noteId;modal('删除这条备忘录？','<p>删除后无法撤销。</p>',`<button class="primary" data-delete-note="${id}">删除</button><button class="secondary" data-action="close-overlay">取消</button>`);break}case'upload-photo':photoTarget='album';$('#photo-file').click();break;case'send-photo':if(pending.has(roomId))return;photoTarget='chat';$('#photo-file').click();break;case'retry':if(state.chats[roomId].length)await sendMessage('',null,true);break;case'chat-more':modal('聊天设置',`<p>与 ${members.find(m=>m.id===roomId).name} 的对话，保存在当前浏览器。</p>`,'<button class="secondary" data-nav="setting:memory">管理重要记忆</button><button class="secondary" data-nav="setting:ai">聊天连接</button><button class="secondary" data-action="clear-chat">清空这段聊天</button>');break;case'clear-chat':modal('清空这段聊天？','<p>只删除当前联系人的聊天记录，其他人的对话和重要记忆不变。</p>','<button class="primary" data-action="confirm-clear-chat">确认清空</button><button class="secondary" data-action="close-overlay">取消</button>');break;case'confirm-clear-chat':if(pending.has(roomId)){toast('请等待当前回复结束');return}state.chats[roomId]=[];delete errors[roomId];save();$('#overlay').innerHTML='';renderChat();break;case'refresh-news':await refreshNews();break;case'add-news':{const text=$('#news-text').value.trim(),url=$('#news-url').value.trim();if(!text||!validUrl(url)){toast('请填写内容与有效的 HTTPS 原文链接');return}if(state.verifiedNews.length>=10){toast('最多保存 10 条公开动态，请先删除旧内容');return}state.verifiedNews.unshift({text:text.slice(0,700),url,date:new Date().toISOString().slice(0,10)});save();renderNews();toast('已加入背景资料');break}case'toggle-stopwatch':if(stopRunning){stopElapsed+=Date.now()-stopStart;stopRunning=false}else{stopStart=Date.now();stopRunning=true}renderClock();break;case'reset-stopwatch':stopElapsed=0;stopStart=Date.now();updateClock();break;case'start-camera':await startCamera();break;case'flip-camera':facing=facing==='user'?'environment':'user';await startCamera();break;case'capture':{const video=$('#camera-video');if(!cameraStream||!video?.videoWidth){toast('请先打开相机');return}const canvas=document.createElement('canvas');const scale=Math.min(1,1100/video.videoWidth);canvas.width=video.videoWidth*scale;canvas.height=video.videoHeight*scale;canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);state.uploads.unshift(canvas.toDataURL('image/jpeg',.8));save();toast('照片已保存到相册');break}case'dial-call':modal('模拟拨号盘','<p>这个网页不会拨打真实电话。想和他们说话，可以前往聊天。</p>','<button class="primary" data-nav="contacts">打开通讯录</button>');break;case'character-info':{const m=members.find(m=>m.id===roomId);modal(m.name+' · 人物资料',`<p>${m.hint}</p><p>设定参考 Weverse Magazine 的公开采访，经过虚构创作。朋友关系与恋爱关系是游戏设定，不是真实私人信息。</p><p><a href="${profileSources[m.id]}" target="_blank" rel="noopener noreferrer">阅读参考采访 ↗</a></p>`);break}}}
const profileSources={jin:'https://magazine.weverse.io/article/view/211?lang=en',rm:'https://magazine.weverse.io/article/view/213?lang=en',suga:'https://magazine.weverse.io/article/view/214?lang=en',jhope:'https://magazine.weverse.io/article/view/1308?lang=en',jimin:'https://magazine.weverse.io/article/view/690?lang=en',v:'https://magazine.weverse.io/article/view/867?lang=en',jk:'https://magazine.weverse.io/article/view/825?lang=en'};
function openApp(app){if(app==='calendar'){navigate('calendar');return}if(app==='music'||app==='spotify'){navigate('spotify');return}if(app==='kkt')chatMode='kkt';navigate(app)}
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-nav]');if(!el)return;lastActive=Date.now();if(el.dataset.nav){navigate(el.dataset.nav);return}if(el.dataset.app){openApp(el.dataset.app);return}if(el.dataset.action){await actions(el.dataset.action,el);return}if(el.dataset.digit){inputDigit(el.dataset.digit);return}if(el.dataset.room){openRoom(el.dataset.room);return}if(el.dataset.contact){roomId=el.dataset.contact;navigate('contact');return}if(el.dataset.suggest){await sendMessage(el.dataset.suggest);return}if(el.dataset.toggle){state[el.dataset.toggle]=!state[el.dataset.toggle];save();renderSetting('display');return}if(el.dataset.wall){state.wall=el.dataset.wall;save();renderSetting('wallpaper');applyAppearance();return}if(el.dataset.removeMemory!==undefined){state.memories.splice(Number(el.dataset.removeMemory),1);save();renderSetting('memory');return}if(el.dataset.photo!==undefined){showPhoto(Number(el.dataset.photo));return}if(el.dataset.photoWall!==undefined){state.customWall=await toDataUrl(allPhotos()[Number(el.dataset.photoWall)]);state.wall='custom';save();$('#overlay').innerHTML='';navigate('home');toast('壁纸已更新');return}if(el.dataset.removeNews!==undefined){state.verifiedNews.splice(Number(el.dataset.removeNews),1);save();renderNews();return}if(el.dataset.month){calendarOffset+=Number(el.dataset.month);renderCalendar();return}if(el.dataset.day){const existing=state.notes.find(n=>n.date===el.dataset.day);if(existing){navigate('note:'+existing.id)}else{const n={id:uid(),text:el.dataset.day+'\n',at:Date.now(),date:el.dataset.day};state.notes.unshift(n);save();navigate('note:'+n.id)}return}if(el.dataset.clock){clockTab=el.dataset.clock;renderClock();return}if(el.dataset.dial){const n=$('#dial-number');n.textContent=(n.textContent+el.dataset.dial).slice(0,18);return}if(el.dataset.deleteNote){state.notes=state.notes.filter(n=>n.id!==el.dataset.deleteNote);save();navigate('notes')}});
document.addEventListener('input',e=>{if(e.target.id==='room-search'){const at=e.target.selectionStart;searchText=e.target.value;renderRooms(page==='messages');$('#room-search').focus();$('#room-search').setSelectionRange(at,at)}if(e.target.id==='global-search')updateSearch(e.target.value);if(e.target.id==='message-input'){e.target.style.height='29px';e.target.style.height=Math.min(e.target.scrollHeight,90)+'px'}});
async function compressImage(file){if(file.size>15*1024*1024)throw Error('请选择小于 15MB 的照片');if(!file.type.startsWith('image/'))throw Error('请选择图片文件');const url=URL.createObjectURL(file);try{return await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const ratio=Math.min(1,1200/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*ratio));c.height=Math.max(1,Math.round(img.height*ratio));c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.78))};img.onerror=()=>reject(Error('无法读取这张图片，请换成 JPG 或 PNG'));img.src=url})}finally{URL.revokeObjectURL(url)}}
async function toDataUrl(src){if(src.startsWith('data:'))return src;const r=await fetch(src);return compressImage(await r.blob())}
$('#wallpaper-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{const image=await compressImage(f);const old={wall:state.wall,customWall:state.customWall};state.customWall=image;state.wall='custom';if(!save())Object.assign(state,old);applyAppearance();if(page==='setting:wallpaper')renderSetting('wallpaper');toast('壁纸已更新')}catch(e){toast(e.message)}e.target.value=''});
$('#photo-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{const data=await compressImage(f);if(photoTarget==='chat'&&page==='chat')await sendMessage('',data);else{state.uploads.unshift(data);if(!save())state.uploads.shift();if(page==='photos')renderPhotos()}}catch(e){toast(e.message)}e.target.value=''});
function validateBackup(s){if(!s||s.version!==2||typeof s.nickname!=='string'||s.nickname.length>24||typeof s.passcode!=='string'||!/^(?:\d{4})?$/.test(s.passcode)||!['jin','dusk','ocean','rose','custom'].includes(s.wall))return false;if(!Array.isArray(s.memories)||s.memories.length>30||!s.memories.every(x=>typeof x==='string'&&x.length<=350))return false;if(!s.chats||!members.every(m=>Array.isArray(s.chats[m.id])&&s.chats[m.id].length<=10000&&s.chats[m.id].every(x=>['user','assistant'].includes(x.role)&&typeof x.text==='string'&&x.text.length<20000&&Number.isFinite(x.at)&&(!x.image||/^data:image\/(jpeg|png|webp);base64,/.test(x.image)))))return false;if(!Array.isArray(s.notes)||!s.notes.every(x=>typeof x.id==='string'&&/^[a-zA-Z0-9-]+$/.test(x.id)&&typeof x.text==='string'&&Number.isFinite(x.at)))return false;if(!Array.isArray(s.uploads)||!s.uploads.every(x=>typeof x==='string'&&/^data:image\/(jpeg|png|webp);base64,/.test(x)))return false;if(s.customWall&&!/^data:image\/(jpeg|png|webp);base64,/.test(s.customWall))return false;if(s.customSound&&(typeof s.customSound!=='string'||s.customSound.length>700000||!/^data:audio\/[a-zA-Z0-9.+-]+;base64,[A-Za-z0-9+/=]+$/.test(s.customSound)))return false;if(!Array.isArray(s.verifiedNews)||!s.verifiedNews.every(x=>typeof x.text==='string'&&validUrl(x.url)&&typeof x.date==='string'))return false;return true}
$('#restore-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(pending.size){toast('请等待正在进行的回复结束后再恢复');return}try{if(f.size>10*1024*1024)throw Error('备份文件过大');const data=JSON.parse(await f.text());if(!validateBackup(data)||!validWorldBackup(data))throw Error('备份格式不正确');modal('恢复这份备份？','<p>这会替换当前浏览器里的手机数据。建议先导出当前备份。</p>','<button class="primary" id="confirm-import">确认恢复</button><button class="secondary" data-action="close-overlay">取消</button>');$('#confirm-import').addEventListener('click',()=>{const old=state;stopWorldVoice();if(worldBubbleTimer)clearTimeout(worldBubbleTimer);worldSceneActive=false;state={...defaultState(),...data};initializeWorldState();if(!save()){state=old;return}navigate('settings');toast('备份已恢复')})}catch(err){toast('无法恢复：'+err.message)}e.target.value=''});
$('#home').addEventListener('click',()=>{if(['lock','passcode'].includes(page))unlock();else navigate('home')});$('#island').addEventListener('click',()=>{if(['lock','passcode'].includes(page))unlock();else navigate('home')});$('#desktop-help').addEventListener('click',()=>navigate('setting:help'));$('#desktop-chat').addEventListener('click',()=>{state.seen=true;save();chatMode='kkt';navigate('kkt')});
$('#control-open').addEventListener('click',()=>{$('#overlay').innerHTML=`<div class="control-center"><div style="display:flex;justify-content:space-between;align-items:center"><h2>控制中心</h2><button class="circle-glass" data-action="close-overlay" aria-label="关闭控制中心">×</button></div><div class="controls-grid"><button class="control-tile active" data-action="network-info">${icon('wifi')}<span>浏览器网络</span></button><button class="control-tile ${state.dark?'active':''}" data-action="control-dark">${icon('moon')}<span>深色外观</span></button><button class="control-tile" data-nav="setting:ai">${icon('chat')}<span>聊天连接</span></button><button class="control-tile" data-nav="lock">${icon('lock')}<span>锁定手机</span></button><div class="control-tile control-wide"><span style="margin-bottom:12px">屏幕亮度 · 页面模拟</span><input id="brightness" type="range" min="65" max="110" value="100" aria-label="模拟亮度"></div><button class="control-tile" data-nav="camera">${icon('camera')}<span>相机</span></button><button class="control-tile" data-nav="settings">${icon('settings')}<span>设置</span></button></div></div>`;$('#brightness').addEventListener('input',e=>screen.style.filter=`brightness(${e.target.value}%)`);$('#overlay').querySelector('[data-action="control-dark"]').onclick=()=>{state.dark=!state.dark;save();applyAppearance();$('#overlay').innerHTML='';render()};$('#overlay').querySelector('[data-action="network-info"]').onclick=()=>toast(navigator.onLine?'浏览器当前在线；实际网络由你的设备管理。':'浏览器当前离线。')});
let touchY=null;screen.addEventListener('touchstart',e=>{if(page==='lock')touchY=e.touches[0].clientY},{passive:true});screen.addEventListener('touchend',e=>{if(page==='lock'&&touchY!==null&&touchY-e.changedTouches[0].clientY>60)unlock();touchY=null},{passive:true});
setInterval(updateTime,1000);setInterval(()=>{if(page==='clock'&&stopRunning)updateClock()},35);window.addEventListener('beforeunload',stopCamera);

let calendarOffset=0;
function renderCalendar(){const now=new Date(),d=new Date(now.getFullYear(),now.getMonth()+calendarOffset,1),y=d.getFullYear(),month=d.getMonth(),days=new Date(y,month+1,0).getDate(),offset=(d.getDay()+6)%7;shell('日历',`<div class="calendar-month"><button data-month="-1" aria-label="上个月">‹</button><strong>${y}年 ${month+1}月</strong><button data-month="1" aria-label="下个月">›</button></div><div class="calendar-grid">${['一','二','三','四','五','六','日'].map(x=>`<small>${x}</small>`).join('')}${Array.from({length:offset},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>{const day=i+1,key=y+'-'+String(month+1).padStart(2,'0')+'-'+String(day).padStart(2,'0');return `<button data-day="${key}" class="${day===now.getDate()&&month===now.getMonth()&&y===now.getFullYear()?'today':''}">${day}${state.notes.some(n=>n.date===key)?'<i></i>':''}</button>`}).join('')}</div><div class="help-card" style="margin-top:25px"><h3>给某一天，留一句话。</h3><p>点击日期添加备忘录，写过的日期会显示一个小圆点。与聊天一样，只保存在当前浏览器。</p></div>`)}


window.addEventListener('storage',event=>{if(event.key===null&&!localResetting){localResetting=true;location.reload()}});
